const NOTIFY_MAP = {
  'person.colm_finn':'notify.mobile_app_np3',
  'person.olivia_finn':'notify.mobile_app_pixel_6a',
  'person.daire_finn':'notify.mobile_app_pixel_9a',
  'person.cian_finn':'notify.pixel_7a'
};
const DEFAULTS = {role:'none',security:false,camera:false,house_mode_change:false,heating_routine:false,heating_freeze:false,infra_alerts:false,only_when_home:false};
const BATTERY_MAP = {
  'person.colm_finn':'sensor.np3_battery_level',
  'person.olivia_finn':'sensor.pixel_6a_battery_level'
};
const PING_MAP = {
  'person.colm_finn':'binary_sensor.colm_phone_home',
  'person.olivia_finn':'binary_sensor.olivia_phone_home',
  'person.daire_finn':'binary_sensor.daire_phone_home'
};

let cfg = {};
try { cfg = JSON.parse(msg.cfgRaw || '{}'); } catch (e) {
  node.warn('person_config.json parse failed, starting from empty: ' + e.message);
  cfg = {};
}

const all = msg.payload || [];
const persons = all.filter(function(e){ return e && e.entity_id && e.entity_id.indexOf('person.') === 0; });
const notifyIds = {};
all.forEach(function(e){ if (e && e.entity_id && e.entity_id.indexOf('notify.') === 0) notifyIds[e.entity_id] = true; });

// Live device_trackers -> matching notify.<same_object_id> entity (how the HA companion
// app names things, e.g. device_tracker.pixel_7a + notify.pixel_7a). Lets a newly linked
// phone (e.g. Aoife's) resolve automatically without a code change — falls back to
// NOTIFY_MAP for the legacy notify.mobile_app_* targets that don't follow that pattern.
function resolveNotify(p) {
  var trackers = (p.attributes && p.attributes.device_trackers) || [];
  for (var i = 0; i < trackers.length; i++) {
    var cand = 'notify.' + trackers[i].split('.').pop();
    if (notifyIds[cand]) return cand;
  }
  return NOTIFY_MAP[p.entity_id] || null;
}

let changed = false;
persons.forEach(function(p){
  var fname = (p.attributes && p.attributes.friendly_name) || p.entity_id;
  if (!cfg[p.entity_id]) {
    cfg[p.entity_id] = Object.assign({}, DEFAULTS, { notify_service: resolveNotify(p), ping: PING_MAP[p.entity_id] || '', name: fname, battery_sensor: BATTERY_MAP[p.entity_id] || null });
    changed = true;
    node.warn('person config: new person ' + p.entity_id + ' auto-added with safe defaults (role none, all off)');
  } else {
    if (cfg[p.entity_id].ping === undefined) { cfg[p.entity_id].ping = PING_MAP[p.entity_id] || ''; changed = true; }
    if (cfg[p.entity_id].name !== fname) { cfg[p.entity_id].name = fname; changed = true; }
    if (cfg[p.entity_id].infra_alerts === undefined) { cfg[p.entity_id].infra_alerts = false; changed = true; }
    if (cfg[p.entity_id].battery_sensor === undefined) { cfg[p.entity_id].battery_sensor = BATTERY_MAP[p.entity_id] || null; changed = true; }
    if (cfg[p.entity_id].only_when_home === undefined) { cfg[p.entity_id].only_when_home = (cfg[p.entity_id].role === 'guest'); changed = true; }
    if (!cfg[p.entity_id].notify_service) {
      var resolved = resolveNotify(p);
      if (resolved) { cfg[p.entity_id].notify_service = resolved; changed = true; node.warn('person config: resolved notify target for ' + p.entity_id + ' -> ' + resolved); }
    }
  }
});

const rows = persons.map(function(p){
  const c = cfg[p.entity_id];
  return Object.assign({
    entity_id: p.entity_id,
    name: (p.attributes && p.attributes.friendly_name) || p.entity_id
  }, c);
});

const ORDER = ['person.colm_finn','person.olivia_finn','person.daire_finn','person.cian_finn','person.aoife_finn'];
rows.sort(function(a,b){
  var ia = ORDER.indexOf(a.entity_id); if (ia === -1) ia = ORDER.length;
  var ib = ORDER.indexOf(b.entity_id); if (ib === -1) ib = ORDER.length;
  if (ia !== ib) return ia - ib;
  return a.name.localeCompare(b.name);
});

global.set('person_config', cfg);

const rowMsg = { payload: rows };
const writeMsg = changed ? { payload: JSON.stringify(cfg, null, 2) } : null;
return [rowMsg, writeMsg];

const row = msg.payload || {};
if (!row.entity_id) return null;

const cfg = global.get('person_config');
if (!cfg) {
  node.warn('pc-save: person_config not loaded yet, refusing to save (would wipe everyone else) — try again in a few seconds');
  return null;
}
const existing = cfg[row.entity_id] || {};
cfg[row.entity_id] = Object.assign({}, existing, {
  role: row.role,
  security: !!row.security,
  camera: !!row.camera,
  house_mode_change: !!row.house_mode_change,
  heating_routine: !!row.heating_routine,
  heating_freeze: !!row.heating_freeze,
  infra_alerts: !!row.infra_alerts,
  notify_service: existing.notify_service !== undefined ? existing.notify_service : (row.notify_service || null),
  battery_sensor: (row.battery_sensor || '').trim() || null,
  only_when_home: !!row.only_when_home
});
global.set('person_config', cfg);
msg.payload = JSON.stringify(cfg, null, 2);
return msg;
